# GENERATED by bench.submit.build_submit_file from deploy/wstc/template_submit.py. Do not edit.
#
# Puts one submission (a prediction made by a model we don't run: timed perimeters, one GeoJSON
# per fire) into the S3 bucket, where the submitted_perimeters block reads it:
#   s3://<bucket>/__PREFIX__/<fire>.geojson
# Only step pods have S3 credentials, so the upload is itself a Dagster job.
#
# Submissions are immutable: a file already in S3 with the same content is left alone; one with
# different content is refused (publish a new version, e.g. .../v2, instead).
import base64
import hashlib
import os

import dagster as dg

ME = "__ME__"
NAME = "__NAME__"
PREFIX = "__PREFIX__"
FILES = __FILES__                # {file name: base64 of its bytes}
DEFAULT_BUCKET = "wstc-dagster"


def _client():
    import boto3
    endpoint = next((os.environ[k] for k in ("AWS_ENDPOINT_URL_S3", "AWS_ENDPOINT_URL", "S3_ENDPOINT_URL")
                     if os.environ.get(k)), None)
    return boto3.client("s3", endpoint_url=endpoint)


@dg.asset(key=dg.AssetKey([ME, "submissions", NAME]), group_name=f"{ME}_submissions",
          kinds={"submission", "s3"},
          description=f"Submission {NAME}: timed perimeters per fire, put in S3 at {PREFIX}/ (a black box: "
                      "geometry and time only).")
def submission(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    from botocore.exceptions import ClientError
    s3, bucket = _client(), os.environ.get("DAGSTER_S3_BUCKET") or DEFAULT_BUCKET
    rows = []
    for name, b64 in sorted(FILES.items()):
        body = base64.b64decode(b64)
        sha, key = hashlib.sha256(body).hexdigest(), f"{PREFIX}/{name}"
        try:
            have = s3.get_object(Bucket=bucket, Key=key)["Body"].read()
        except ClientError as e:
            if e.response.get("Error", {}).get("Code") not in ("NoSuchKey", "404", "NotFound"):
                raise
            have = None
        if have is not None and hashlib.sha256(have).hexdigest() != sha:
            raise dg.Failure(f"s3://{bucket}/{key} already exists with different content; submissions are "
                             "immutable, so publish this as a new version (a new prefix)")
        status = "already there" if have is not None else "uploaded"
        if have is None:
            s3.put_object(Bucket=bucket, Key=key, Body=body, ContentType="application/geo+json")
        context.log.info(f"{status}: s3://{bucket}/{key} ({len(body):,} bytes)")
        rows.append({"file": name, "status": status, "bytes": len(body), "sha256": sha[:16]})
    table = "| file | status | bytes | sha256 |\n|---|---|---|---|\n" + "\n".join(
        f"| {r['file']} | {r['status']} | {r['bytes']:,} | {r['sha256']} |" for r in rows)
    return dg.MaterializeResult(metadata={"uri": f"s3://{bucket}/{PREFIX}/", "files": len(rows),
                                          "table": dg.MetadataValue.md(table)})


defs = dg.Definitions(assets=[submission],
                      jobs=[dg.define_asset_job(f"{ME}_submit_{NAME}_job", selection=[submission])])
